// 1. 跨节点去 Webhook 源头捞取人工修改后的数据
const webhookData = $('Webhook').first().json.body; 

const project_details = webhookData.project_details || [];
const notes = webhookData.customer_questions_answered || "无";

// 2. 重新核算总价
let total_amount = 0;
project_details.forEach(item => {
    total_amount += (Number(item.total_price) || 0);
});

// 3. 渲染精美的 Markdown 文本
let markdown = `### 🏠 AI智能报价单 (人工核准版)\n\n`;
markdown += `> **客户疑问解答:** ${notes}\n\n`;
markdown += `| 施工项目 | 单价 | 合计 | 备注 |\n`;
markdown += `| :--- | :--- | :--- | :--- |\n`;
project_details.forEach(item => {
    markdown += `| ${item.project_name} | ¥${item.unit_price} | **¥${item.total_price}** | ${item.notes} |\n`;
});
markdown += `\n**💰 人工最终核准总计: ¥${total_amount.toFixed(2)}**`;

// 🚀 4. 新增核心：直接在这里组装好钉钉 API 需要的严格 JSON 格式
const dingtalk_payload = {
    "msgtype": "markdown",
    "markdown": {
        "title": "AI智能报价单(人工核准)",
        "text": markdown
    }
};

// 5. 完美输出三路数据
return {
    db_record: {
        customer_name: "大屏录入客户", 
        total_amount: total_amount,
        details_json: JSON.stringify(project_details)
    },
    dingtalk_payload: dingtalk_payload, // 专供钉钉文本推送通道
    project_details: project_details    // 专供下游 Excel 拆分通道
};

const inputData = $input.all()[0].json;
const details = inputData.project_details || [];
const result = [];

// 如果大模型真的没抽出数据，塞入一行空提示，强制激活后续流程不中断！
