            "施工项目": row.project_name,
            "AI核准单价(元)": row.unit_price,
            "项目合计(元)": row.total_price,
            "工艺与避坑备注": row.notes
        }
    });
}
return result;

const crypto = require('crypto');
const secret = '019483697d32bcfe5ba55084d4ad23d5f244fb1662b92db9e0c9b0f871c832d9';

const headers = $input.first().json.headers;
const body = $input.first().json.body;

const receivedSig = (headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '').trim();
if (!receivedSig) {
  throw new Error('[HMAC] Rejected: missing X-Webhook-Signature header');
}

const bodyStr = JSON.stringify(body);
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyStr, 'utf8').digest('hex');

const maxLen = Math.max(receivedSig.length, expectedSig.length);
const rcvBuf = Buffer.from(receivedSig.padEnd(maxLen));
const expBuf = Buffer.from(expectedSig.padEnd(maxLen));
if (!crypto.timingSafeEqual(rcvBuf, expBuf)) {
  throw new Error('[HMAC] Rejected: signature mismatch');
}

return $input.all();

