// 部署位置：n8n 工作流中，Dify 请求节点之后的 Code 节点。
// 修复说明：精准适配 Dify 根节点 Token 与耗时输出，加入 deepseek-reasoner 计费规则。

const items = $input.all();
const processedData = [];

// ==========================================
// 架构配置：企业级商用大模型单价池 (单位：人民币元 / 千Token)
// ==========================================
const PRICING_TIERS = {
    "deepseek-reasoner": { average: 0.012 }, // DeepSeek R1 均价预估
    "qwen-max": { average: 0.08 },
    "dify-bge-default": { average: 0.02 }
};

const MODEL_IN_USE = "deepseek-reasoner"; 

for (let i = 0; i < items.length; i++) {
    const item = items[i].json;

    // 1. 适配 Dify 根节点数据结构
    const total_tokens = item.total_tokens || 0;
    const latencyMs = item.elapsed_time ? Math.round(item.elapsed_time * 1000) : 0; 

    // 2. 核心核算：计算真金白银成本
    const totalCostRMB = (total_tokens / 1000) * PRICING_TIERS[MODEL_IN_USE].average;

    // 3. 监控预警阈值判定 (Guardrails)
    let alertStatus = "NORMAL";
    let alertMessage = "请求健康";

    if (totalCostRMB > 0.1) {
        alertStatus = "WARNING_HIGH_COST";
        alertMessage = `算力消耗过载: ¥${totalCostRMB.toFixed(4)}`;
    }

    // 针对 deepseek-reasoner (R1) 这种深度思考模型，放宽延迟监控阈值至 60 秒
    if (latencyMs > 60000) { 
         alertStatus = alertStatus === "NORMAL" ? "WARNING_HIGH_LATENCY" : alertStatus + "_AND_LATENCY";
         alertMessage += ` | 响应延迟违规: ${latencyMs}ms`;
    }

    // 4. 封装可观测性探针
    processedData.push({
        json: {
            ...item,
            llmops_metrics: {
                model_name: MODEL_IN_USE,
                tokens: { total_tokens: total_tokens },
                cost_rmb: parseFloat(totalCostRMB.toFixed(6)),
                latency_ms: latencyMs,
                alert_status: alertStatus,
                alert_message: alertMessage,
                timestamp: new Date().toISOString()
            }
        }
    });
}

return processedData;

const items = $input.all();
const result = [];

for (let i = 0; i < items.length; i++) {
    let item = items[i].json;
    let finalJson = { project_details: [], customer_questions_answered: "未提取到有效数据" };

    try {
        let rawText = item.answer || (item.data && item.data.outputs && item.data.outputs.text) || JSON.stringify(item);

        // 🚀 核心 1：暴力切除 DeepSeek 的 <think> 思考过程干扰
        rawText = rawText.replace(/<think>[\s\S]*?<\/think>/gi, '');

        let jsonStr = "";
        // 🚀 核心 2：使用 \x60 代替反引号，精准提取 JSON
        const regex = /\x60\x60\x60(?:json)?\s*([\s\S]*?)\s*\x60\x60\x60/i;
        const match = rawText.match(regex);

        if (match && match[1]) {
            jsonStr = match[1];
        } else {
            const start = rawText.indexOf('{');
            const end = rawText.lastIndexOf('}');
            if (start !== -1 && end !== -1) {
                jsonStr = rawText.substring(start, end + 1);
            } else {
                jsonStr = rawText;
            }
        }

        // 🚀 核心 3：双保险解析，过滤掉大模型幻觉换行符
        let parsed = null;
        try {
            parsed = JSON.parse(jsonStr);
        } catch(e1) {
            jsonStr = jsonStr.replace(/[\n\r\t]/g, "");
            parsed = JSON.parse(jsonStr);
        }

        // 🚀 核心 4：字段名强制纠错 (防止大模型输出 item_name 导致表格读取不到)
        if (parsed && parsed.project_details) {
            finalJson.project_details = parsed.project_details.map(p => ({
                project_name: p.project_name || p.item_name || p.name || "未知项目",
                unit_price: Number(p.unit_price) || 0,
                total_price: Number(p.total_price) || 0,
                notes: p.notes || p.remark || ""
            }));
            finalJson.customer_questions_answered = parsed.customer_questions_answered || "无";
        }
    } catch(e) {
        console.log("解析彻底失败:", e.message);
    }

    result.push({ json: finalJson });
}

return result;

