    let cleanJsonStr = rawText.replace(/<think>[\s\S]*?<\/think>/g, '') 
                              .replace(/```json/g, '') 
                              .replace(/```/g, '') 
                              .trim();

    const parsedData = JSON.parse(cleanJsonStr);
