    let markdownTable = "| 施工项目 | 单价 | 本项合计 | 备注 |\n| --- | --- | --- | --- |\n";
    parsedData.project_details.forEach(item => {
        markdownTable += `| ${item.project_name} | ${item.unit_price} | **${item.total_price}** | ${item.notes} |\n`;
    });

    const dingtalkResponse = {
        "msgtype": "markdown",
        "markdown": {
            "title": "预算核算完毕",
            "text": `### 🤖 AI预算师核算完毕\n\n**💰 系统严密核算总价：** <font color="#ff0000">${finalTotal}</font> 元\n\n**⚠️ 客户疑点解答：** ${parsedData.customer_questions_answered}\n\n---\n**📋 预算明细清单：**\n\n${markdownTable}`
        }
    };

  // 【新增打磨】将底层英文 JSON 映射为对客户友好的中文表头
    const chineseExcelRows = parsedData.project_details.map(item => ({
        "施工项目": item.project_name,
        "单价(元)": item.unit_price,
        "本项合计(元)": item.total_price,
        "工艺与备注说明": item.notes
    }));

    // 【1. 锁定原始文本 (采用全新变量名防冲突)】
    let dingtalkMsg = "";
    try {
        dingtalkMsg = $('Webhook').first().json.body.text.content;
    } catch (e) {
        dingtalkMsg = ""; // 架构师防瘫痪兜底
    }

    // 【2. 正则抓取引擎】
    let customerName = "未知客户"; 

    if (dingtalkMsg) {
        const nameMatch = dingtalkMsg.match(/客户([^\uff0c，。\s]+)/);
        if (nameMatch && nameMatch[1]) {
            customerName = nameMatch[1].trim(); 
        }
    }

    // 【终极重构】把数据兵分三路！(请确保你代码最后是这部分)
    return {
        markdown_msg: dingtalkResponse,      
        excel_rows: chineseExcelRows,        
        db_record: {                         
            customer_name: customerName,     
            total_amount: finalTotal,
            details_json: JSON.stringify(chineseExcelRows) 
        }
    };


} catch (error) {
    return {
        markdown_msg: {
            "msgtype": "text",
            "text": { "content": "收到系统心跳/校验请求，或者解析失败。" }
        }
    };
}

